import React, { useEffect, useMemo, useState } from "react";
import { useSearchParams } from "react-router-dom";
import DashboardLayout from "../components/DashboardLayout";
import api from "../services/api";
import { useAuth } from "../context/AuthContext";

const AttendanceReports = () => {
  const { user } = useAuth();
  const isTeacher = user?.role === "teacher";
  const [searchParams, setSearchParams] = useSearchParams();

  const initialMode = searchParams.get("mode") || "date";
  const [filterMode, setFilterMode] = useState(initialMode);
  const [date, setDate] = useState(searchParams.get("date") || new Date().toISOString().slice(0, 10));
  const [month, setMonth] = useState(searchParams.get("month") || new Date().toISOString().slice(0, 7));
  const [year, setYear] = useState(searchParams.get("year") || String(new Date().getFullYear()));
  const [records, setRecords] = useState([]);
  const [apiError, setApiError] = useState("");

  const params = useMemo(() => {
    if (filterMode === "month") {
      return { month };
    }
    if (filterMode === "year") {
      return { year };
    }
    return { date };
  }, [filterMode, date, month, year]);

  useEffect(() => {
    const next = new URLSearchParams();
    next.set("mode", filterMode);
    if (filterMode === "date") {
      next.set("date", date);
    }
    if (filterMode === "month") {
      next.set("month", month);
    }
    if (filterMode === "year") {
      next.set("year", year);
    }
    setSearchParams(next, { replace: true });
  }, [filterMode, date, month, year, setSearchParams]);

  useEffect(() => {
    const load = async () => {
      setApiError("");
      try {
        const endpoint = isTeacher ? "/teacher/attendance" : "/attendance/history";
        const res = await api.get(endpoint, { params });
        setRecords(res.data.records || []);
      } catch (error) {
        setApiError(error.response?.data?.message || "Failed to load attendance report");
      }
    };
    load();
  }, [isTeacher, params]);

  const figures = useMemo(() => {
    const total = records.length;
    const present = records.filter((r) => r.status === "Present").length;
    const absent = records.filter((r) => r.status === "Absent").length;
    const late = records.filter((r) => r.status === "Late").length;
    const toPercent = (n) => (total ? Number(((n / total) * 100).toFixed(2)) : 0);

    return {
      total,
      present,
      absent,
      late,
      presentPct: toPercent(present),
      absentPct: toPercent(absent),
      latePct: toPercent(late),
    };
  }, [records]);

  const pieStyle = useMemo(() => {
    const p = figures.presentPct;
    const a = figures.absentPct;
    const l = figures.latePct;
    return {
      background: `conic-gradient(#16a34a 0% ${p}%, #ef4444 ${p}% ${p + a}%, #f59e0b ${p + a}% ${p + a + l}%, #e2e8f0 ${p + a + l}% 100%)`,
    };
  }, [figures]);

  return (
    <DashboardLayout title="Attendance Reports">
      <div className="panel">
        <label>Attendence Filter</label>
        <div className="filter-mode-row">
          <button
            type="button"
            className={`filter-mode-btn ${filterMode === "date" ? "active" : ""}`}
            onClick={() => setFilterMode("date")}
          >
            Calendar Date
          </button>
          <button
            type="button"
            className={`filter-mode-btn ${filterMode === "month" ? "active" : ""}`}
            onClick={() => setFilterMode("month")}
          >
            Monthly
          </button>
          <button
            type="button"
            className={`filter-mode-btn ${filterMode === "year" ? "active" : ""}`}
            onClick={() => setFilterMode("year")}
          >
            Yearly
          </button>
        </div>

        {filterMode === "date" && (
          <>
            <label>Date</label>
            <input type="date" value={date} onChange={(event) => setDate(event.target.value)} />
          </>
        )}
        {filterMode === "month" && (
          <>
            <label>Month</label>
            <input type="month" value={month} onChange={(event) => setMonth(event.target.value)} />
          </>
        )}
        {filterMode === "year" && (
          <>
            <label>Year</label>
            <input type="number" min="2000" max="2100" value={year} onChange={(event) => setYear(event.target.value)} />
          </>
        )}
      </div>

      {apiError && <div className="panel"><div className="error-text">{apiError}</div></div>}

      <div className="cards-grid">
        <div className="stat-card"><h3>Total Records</h3><p>{figures.total}</p></div>
        <div className="stat-card"><h3>Present</h3><p>{figures.present}</p></div>
        <div className="stat-card"><h3>Absent</h3><p>{figures.absent}</p></div>
        <div className="stat-card"><h3>Late</h3><p>{figures.late}</p></div>
      </div>

      <div className="panel report-grid">
        <div className="pie-wrap">
          <div className="pie-chart" style={pieStyle} />
        </div>
        <div>
          <h3>Percentages</h3>
          <p>Present: {figures.presentPct}%</p>
          <p>Absent: {figures.absentPct}%</p>
          <p>Late: {figures.latePct}%</p>
          <div className="legend-row">
            <span className="legend-dot present" /> Present
            <span className="legend-dot absent" /> Absent
            <span className="legend-dot late" /> Late
          </div>
        </div>
      </div>

      <div className="panel">
        <h3>Attendance Records</h3>
        <div className="table-wrap">
          <table className="table">
            <thead>
              <tr>
                <th>Date</th>
                <th>Student</th>
                <th>Class</th>
                <th>Status</th>
              </tr>
            </thead>
            <tbody>
              {records.length > 0 ? (
                records.map((record) => (
                  <tr key={record.id}>
                    <td>{record.date}</td>
                    <td>{record.student?.name}</td>
                    <td>{record.student?.class_grade}-{record.student?.division}</td>
                    <td>{record.status}</td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="4" className="empty-cell">No attendance records</td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </DashboardLayout>
  );
};

export default AttendanceReports;
